/* filter_lab_hooks.h - the hooks the lab copy of the engine (filter_lab_engine.c, generated by tools/gen_filter_lab_engine.py) calls
 * in place of its two inlined filter statements and of the rapid-trigger distance floor. Implemented in filter_lab.c. */
#ifndef FILTER_LAB_HOOKS_H
#define FILTER_LAB_HOOKS_H

#include <stdint.h>

/* new value of the main filter f (counts << 4) from the old f and the new reading x (counts << 4); the engine's own: f + ((x - f) >> 2) */
int32_t lab_hook_stage1(int32_t f, int32_t x_q4);
/* new value of the rapid-trigger slow stage g from the old g and the main filter f; the engine's own: g + (((f - g) + 4) >> 3) */
int32_t lab_hook_stage2(int32_t g, int32_t f);
/* smallest rt_down / rt_up the lab engine accepts (the real engine: KM_ENGINE_RT_MIN_MM100 = 20) */
extern uint16_t lab_rt_floor;

#endif
